use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::ParseActorIdError;

/// Defines a 128-bit id newtype that prints as 32 hex digits. Ids are
/// generated by shell crates (UUID v7); pure crates only carry them.
macro_rules! hex_id {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
        pub struct $name(pub u128);

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{:032x}", self.0)
            }
        }

        impl FromStr for $name {
            type Err = ParseActorIdError;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                s.parse::<crate::ActorId>().map(|id| Self(id.0))
            }
        }
    };
}

hex_id!(
    /// A shared history: a thread together with its forks.
    FamilyId
);
hex_id!(
    /// One line of work (a conversation and the code it changes) within a family.
    ThreadId
);
hex_id!(
    /// A machine running a Silt daemon.
    DeviceId
);

/// BLAKE3 hash of a stored blob.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct BlobHash(pub [u8; 32]);

impl fmt::Display for BlobHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for byte in self.0 {
            write!(f, "{byte:02x}")?;
        }
        Ok(())
    }
}

impl fmt::Debug for BlobHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "BlobHash({self})")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_round_trip_as_hex() {
        let thread = ThreadId(0x0001_92ab);
        assert_eq!(thread.to_string().parse::<ThreadId>(), Ok(thread));
    }
}
